% The blocks in this sub-section record the project-local infrastructure that fills the explicit
% TODO of Mathlib's `Topology/Sheaves/Over.lean`: the equivalence of sheaf categories induced by
% the site equivalence `Opens.overEquivalence U`. Together with the three Mathlib dependency
% anchors below they form the topos-theoretic (purely topological) layer of bridge C
% (\cref{lem:over_restrict_iso}); the geometric identification of the structure sheaves is the
% layer above them.

\begin{lemma}[Slice of opens equivalent to opens of the open subspace]
  \label{lem:opens_overEquivalence_mathlib}
  \lean{TopologicalSpace.Opens.overEquivalence}
  \mathlibok
  \textit{Provided by Mathlib (\texttt{Mathlib.Topology.Sheaves.Over}).}
  For a topological space \(X\) and an open \(U \subseteq X\), the slice category of opens of
  \(X\) over \(U\) (the opens of \(X\) contained in \(U\), with inclusions) is equivalent to the
  opens of the subspace \(U\):
  \((\mathrm{Opens}\,X)_{/U} \simeq \mathrm{Opens}(U)\). Mathlib supplies this underlying
  equivalence of sites; it leaves the lift to sheaf categories as an explicit TODO.
\end{lemma}

\begin{lemma}[Sheaf categories of equivalent sites are equivalent]
  \label{lem:equivalence_sheafCongr_mathlib}
  \lean{CategoryTheory.Equivalence.sheafCongr}
  \mathlibok
  \textit{Provided by Mathlib (\texttt{Mathlib.CategoryTheory.Sites.Equivalence}).}
  Let \(e : C \simeq D\) be an equivalence of categories carrying Grothendieck topologies \(J\)
  on \(C\) and \(K\) on \(D\), and suppose \(e.\mathrm{inverse}\) is a dense subsite for
  \((K, J)\). Then for any target category \(A\) the sheaf categories are equivalent:
  \(\mathrm{Sheaf}(J, A) \simeq \mathrm{Sheaf}(K, A)\).
\end{lemma}

\begin{lemma}[Module sheaves transport across an equivalence of ringed sites]
  \label{lem:pushforwardPushforwardEquivalence_mathlib}
  \lean{SheafOfModules.pushforwardPushforwardEquivalence}
  \mathlibok
  \textit{Provided by Mathlib
  (\texttt{Mathlib.Algebra.Category.ModuleCat.Sheaf.PushforwardContinuous}).}
  Let \(e : C \simeq D\) be an equivalence of sites with both \(e.\mathrm{functor}\) and
  \(e.\mathrm{inverse}\) continuous, and let \(S\) (a sheaf of rings on \(J\)) and \(R\) (a sheaf
  of rings on \(K\)) be related by mutually inverse comparison maps across the continuous
  pushforwards. Then the categories of sheaves of modules are equivalent,
  \(\mathrm{SheafOfModules}\,R \simeq \mathrm{SheafOfModules}\,S\), compatibly with the
  underlying ring-sheaf identification. This is the module-level lift used in step~3 of
  \cref{lem:over_restrict_iso}.
\end{lemma}

\begin{lemma}\leanok
[The over-equivalence functor is cocontinuous]
  \label{lem:overEquivalence_functor_isCocontinuous}
  \lean{AlgebraicGeometry.overEquivalence_functor_isCocontinuous}
  \uses{lem:opens_overEquivalence_mathlib}
  \textit{Topological layer of bridge C; fills the \texttt{Topology/Sheaves/Over.lean} TODO.}
  The functor of \(\mathrm{Opens.overEquivalence}\,U\) (\cref{lem:opens_overEquivalence_mathlib})
  is cocontinuous (cover-lifting) from the \(U\)-slice \(J_X|_U\) of the opens Grothendieck
  topology of \(X\) to the opens Grothendieck topology \(J_U\) of the subspace \(U\).
\end{lemma}
\begin{proof}
  \uses{lem:opens_overEquivalence_mathlib}
  A sieve covers in the slice topology \(J_X|_U\) iff its image sieve covers in \(J_X\), and
  covering for the opens topology is pointwise: a sieve covers iff its members' opens cover the
  base set-theoretically. Given a point \(x\) of a slice object and a cover member in \(J_U\)
  containing the image of \(x\), transport it across the open embedding \(U \hookrightarrow X\),
  \textit{Provided by Mathlib.}
  For \(M\) an \(R\)-module and \(f \in R\), Mathlib's map
  \(\operatorname{toOpen} : M \to \Gamma(D(f), \widetilde{M})\) exhibits \(\Gamma(D(f), \widetilde{M}) =
  M_f\) as the localization of \(M\) at the powers of \(f\): it carries an
  \(\operatorname{IsLocalizedModule}(\operatorname{powers} f)\) instance. Moreover the global component
  \(\operatorname{toOpen}(M, \top)\) is an isomorphism (Mathlib's
  \(\operatorname{isIso\_toOpen\_top}\)), identifying \(\Gamma(\operatorname{Spec} R, \widetilde{M}) =
  M\).
\end{lemma}

\begin{lemma}[Transport of a presentation along a colimit-preserving functor]
  \label{lem:presentation_map_mathlib}
  \lean{SheafOfModules.Presentation.map}
  \mathlibok
  \textit{Provided by Mathlib.}
  Let \(F : \operatorname{SheafOfModules} R \to \operatorname{SheafOfModules} S\) be a functor between
  categories of sheaves of modules (possibly over different sites) that preserves colimits and carries
  the unit object to the unit object, \(F(\mathcal{O}_R) \cong \mathcal{O}_S\). Then any presentation
  of a sheaf of modules \(\mathcal{M}\) — a right-exact sequence
  \(\mathcal{O}_R^{(J)} \to \mathcal{O}_R^{(I)} \to \mathcal{M} \to 0\) of generators and relations —
  is carried by \(F\) to a presentation of \(F(\mathcal{M})\).
\end{lemma}

\begin{lemma}[Transport of a presentation across an isomorphism]
  \label{lem:presentation_ofIsIso_mathlib}
  \lean{SheafOfModules.Presentation.ofIsIso}
  \mathlibok
  \textit{Provided by Mathlib.}
  Let \(\phi : \mathcal{M} \to \mathcal{N}\) be an isomorphism of sheaves of modules. A presentation of
  \(\mathcal{M}\) induces a presentation of \(\mathcal{N}\), by composing its generators and relations
  with \(\phi\).
\end{lemma}

\begin{lemma}[Site-equivalence transport of sheaves of modules]
  \label{lem:pushforwardPushforwardEquivalence_mathlib}
  \lean{SheafOfModules.pushforwardPushforwardEquivalence}
  \mathlibok
  \textit{Provided by Mathlib.}
  Let \(e : \mathcal{C} \simeq \mathcal{D}\) be an equivalence of sites and let
  \(\mathcal{O}_{\mathcal{C}}\), \(\mathcal{O}_{\mathcal{D}}\) be sheaves of rings related by
  compatible comparison maps along \(e\). Then \(e\) induces an equivalence of categories of sheaves of
  modules \(\operatorname{SheafOfModules} \mathcal{O}_{\mathcal{C}} \simeq
  \operatorname{SheafOfModules} \mathcal{O}_{\mathcal{D}}\), compatible with the underlying
  pushforwards. This is the engine that bridges two pictures of ``restriction to an open''.
\end{lemma}

\begin{lemma}[The over-site of a topological space is equivalent to its subspace site]
  \label{lem:overEquivalence_mathlib}
  \lean{TopologicalSpace.Opens.overEquivalence}
  \mathlibok
  \textit{Provided by Mathlib.}
  For a topological space \(T\) and an open \(U \subseteq T\), the over-category
  \((\operatorname{Opens} T).\operatorname{over} U\) of opens contained in \(U\) is equivalent to the
  category \(\operatorname{Opens} U\) of opens of the subspace \(U\).
\end{lemma}

\begin{lemma}[Continuity of the over-site equivalence]
  \label{lem:overEquivalence_isContinuous}
  \lean{AlgebraicGeometry.Opens.overEquivalence_functor_coverPreserving,
    AlgebraicGeometry.Opens.overEquivalence_inverse_coverPreserving,
    AlgebraicGeometry.Opens.overEquivalence_functor_isContinuous,
    AlgebraicGeometry.Opens.overEquivalence_inverse_isContinuous,
    AlgebraicGeometry.overEquivalence_functor_isContinuous_toScheme,
    AlgebraicGeometry.overEquivalence_inverse_isContinuous_toScheme}
  \uses{lem:overEquivalence_mathlib}
  Both functors of the over-site equivalence

      \iota_i^{*}\bigl((\iota_j)_{*}\,\mathcal{M}_j\bigr)
        \;\xrightarrow{\ \sim\ }\;
      (f_{ij})_{*}\bigl((t_{ij}\circ f_{ji})^{*}\,\mathcal{M}_j\bigr),
  \]
  evaluated at the input sheaf \(\mathcal{M}_j\).
\end{definition}

\begin{definition}\leanok
[The \(j\)-th component of the candidate inverse]
  \label{def:gr_glueChartComponent}
  \lean{AlgebraicGeometry.Scheme.Modules.glueChartComponent}
  \uses{def:gr_glueOverlapFactorIso}
  Given the transition isomorphisms \(g_{ij} : f_{ij}^{*}\mathcal{M}_i \xrightarrow{\sim}
  (t_{ij}\circ f_{ji})^{*}\mathcal{M}_j\), the \(j\)-th component of the candidate
  inverse \(\mathrm{s}_i\) is the composite
  \[
    \mathcal{M}_i
      \xrightarrow{\ \eta_{f_{ij}}\ }
    (f_{ij})_{*}\,f_{ij}^{*}\mathcal{M}_i
      \xrightarrow{\ (f_{ij})_{*}g_{ij}\ }
    (f_{ij})_{*}\,(t_{ij}\circ f_{ji})^{*}\mathcal{M}_j
      \xrightarrow{\ \gamma_{ij}^{-1}\ }
    \iota_i^{*}\bigl((\iota_j)_{*}\mathcal{M}_j\bigr),
  \]
  i.e. the geometric unit along \(f_{ij}\), the pushforward of the transition
  \(g_{ij}\), and the inverse of \(\gamma_{ij}\) (\cref{def:gr_glueOverlapFactorIso}).
\end{definition}

\begin{definition}\leanok
[The candidate-inverse family]
  \label{def:gr_glueChartFamily}
  \lean{AlgebraicGeometry.Scheme.Modules.glueChartFamily}
  \uses{def:gr_glueChartComponent, def:gr_glue_equalizer}
  Assembling the components \cref{def:gr_glueChartComponent} through the
  product-preservation comparison of \(\iota_i^{*}\) on the pushforward product
  \(P = \prod_j (\iota_j)_{*}\mathcal{M}_j\) (\cref{def:gr_glue_equalizer}) gives a
  single morphism
  \[
    \mathcal{M}_i \;\longrightarrow\; \iota_i^{*}P,
  \]
  the candidate inverse before it is corrected to land in the equalizer
  \(\iota_i^{*}\mathcal{M}\).
\end{definition}

\subsection{The triple-overlap toolkit}

The first descent obligation (\cref{lem:gr_glueChartFamily_equalizes}) reduces, factor
by factor of the restricted overlap product, to a single equation over a \emph{triple
overlap}. This subsection records that machinery. Fix three chart indices \(i, p, q\)
and form the triple overlap
\[
  V_{ipq} \;=\; V_{ip} \times_{U_i} V_{iq},
\]
with first projection \(\mathrm{fst} : V_{ipq} \to V_{ip}\). Two morphisms out of
\(V_{ipq}\) organise everything: the \emph{chart leg}
\(q_{pq} = \mathrm{fst}\circ f_{ip} : V_{ipq} \to U_i\) (down to \(U_i\)), and the
\emph{transport leg} \(\tau = t'_{ipq}\circ \mathrm{fst}_{pq} : V_{ipq} \to V_{pq}\)
(across to the pair overlap, through the cocycle transport \(t'_{ipq}\)). The square
\[
  \begin{array}{ccc}
    V_{ipq} & \xrightarrow{\ \ \tau\ \ } & V_{pq} \\
    \ \downarrow{\scriptstyle q_{pq}} & & \downarrow{\scriptstyle f_{pq}\circ \iota_p} \\
    U_i & \xrightarrow{\ \ \iota_i\ \ } & X
  \end{array}
\]
is the triple analogue of the chart--overlap square of \cref{lem:glueOverlapBaseChangeIso}.

\begin{lemma}

[Triple-overlap bridges of the glue datum]
  \label{lem:gr_glueData_bridges}
  \lean{AlgebraicGeometry.Scheme.Modules.glueData_bridge_src,
    AlgebraicGeometry.Scheme.Modules.glueData_bridge_mid,
    AlgebraicGeometry.Scheme.Modules.glueData_bridge_tgt}
  \uses{def:scheme_modules_glue}
  On the triple overlap \(V_{ijk} = V_{ij}\times_{U_i} V_{ik}\) the following three
  identities of morphisms hold, lining up the endpoints of the three base-change
  transports of the cocycle equation (C2):
  \begin{enumerate}
    \item \emph{(source)} the two projections of \(V_{ijk}\) to \(V_{ij}\) and \(V_{ik}\),
      followed by the overlap immersions \(f_{ij}\) and \(f_{ik}\) into \(U_i\),
      agree;
    \item \emph{(middle)} the \(ij\)-transport's target leg
      \((t_{ij}\circ f_{ji})\) and the \(jk\)-transport's source leg
      (through the cocycle transport \(t'_{ijk}\) and \(f_{jk}\)) agree as morphisms
      to \(U_j\);
    \item \emph{(target)} the composite \(jk\)-after-\(ij\) transport's target leg
      \((t_{jk}\circ f_{kj})\) and the \(ik\)-transport's target leg
      \((t_{ik}\circ f_{ki})\) agree as morphisms to \(U_k\).
  \end{enumerate}
\end{lemma}
\begin{proof}
  \uses{def:scheme_modules_glue}
  The source identity is the universal property (pullback condition) of \(V_{ijk}\).
  The middle identity follows from the transition factorisation
  \(t'_{ijk}\) of \cref{def:scheme_modules_glue} together with the pullback condition.

